diff --git a/lib/eslint/eslint.js b/lib/eslint/eslint.js
index 99bddf2..89b8e29 100644
--- a/lib/eslint/eslint.js
+++ b/lib/eslint/eslint.js
@@ -530,6 +530,17 @@ class ESLint {
 			throw new Error("'results' must be an array");
 		}

+		/*
+		 * Writing every file at once can exhaust the available file descriptors
+		 * when there are many fixed files, resulting in EMFILE or ENFILE errors.
+		 * Limit the number of concurrent writes and retry those that fail due to
+		 * the system running out of file handles.
+		 */
+		const retryCodes = new Set(["ENFILE", "EMFILE"]);
+		const retrier = new Retrier(error => retryCodes.has(error.code), {
+			concurrency: 100,
+		});
+
 		await Promise.all(
 			results
 				.filter(result => {
@@ -541,7 +552,9 @@ class ESLint {
 						path.isAbsolute(result.filePath)
 					);
 				})
-				.map(r => fs.writeFile(r.filePath, r.output)),
+				.map(r =>
+					retrier.retry(() => fs.writeFile(r.filePath, r.output)),
+				),
 		);
 	}

