+			it("should retry writing a file when fs.writeFile() fails with EMFILE or ENFILE", async () => {
+				const attempts = new Map();
+				const written = [];
+				const spy = sinon.spy(async (filePath, output) => {
+					const attempt = (attempts.get(filePath) ?? 0) + 1;
+
+					attempts.set(filePath, attempt);
+
+					if (attempt === 1) {
+						const error = new Error(
+							`EMFILE: too many open files, open '${filePath}'`,
+						);
+
+						error.code = filePath.endsWith("foo.js")
+							? "EMFILE"
+							: "ENFILE";
+						throw error;
+					}
+
+					written.push([filePath, output]);
+				});
+				const { ESLint: localESLint } = proxyquire(
+					"../../../lib/eslint/eslint",
+					{
+						"node:fs/promises": {
+							writeFile: spy,
+						},
+					},
+				);
+
+				const results = [
+					{
+						filePath: path.resolve("foo.js"),
+						output: "bar",
+					},
+					{
+						filePath: path.resolve("bar.js"),
+						output: "baz",
+					},
+				];
+
+				await localESLint.outputFixes(results);
+
+				assert.strictEqual(spy.callCount, 4);
+				assert.deepStrictEqual(
+					[...written].sort(([a], [b]) => a.localeCompare(b)),
+					[
+						[path.resolve("bar.js"), "baz"],
+						[path.resolve("foo.js"), "bar"],
+					],
+				);
+			});
+
+			it("should not write more files at once than the concurrency limit", async () => {
+				const total = 500;
+				let inFlight = 0;
+				let maxInFlight = 0;
+				let completed = 0;
+				const spy = sinon.spy(async () => {
+					inFlight++;
+					maxInFlight = Math.max(maxInFlight, inFlight);
+
+					await timers.setImmediate();
