+					inFlight--;
+					completed++;
+				});
+				const { ESLint: localESLint } = proxyquire(
+					"../../../lib/eslint/eslint",
+					{
+						"node:fs/promises": {
+							writeFile: spy,
+						},
+					},
+				);
+
+				const results = Array.from({ length: total }, (_, i) => ({
+					filePath: path.resolve(`file${i}.js`),
+					output: `output${i}`,
+				}));
+
+				await localESLint.outputFixes(results);
+
+				assert.strictEqual(spy.callCount, total);
+				assert.strictEqual(completed, total);
+				assert(
+					maxInFlight <= 100,
+					`Expected at most 100 concurrent writes, but got ${maxInFlight}.`,
+				);
+			});
+
+			it("should reject if fs.writeFile() fails with an error other than EMFILE or ENFILE", async () => {
+				const spy = sinon.spy(async () => {
+					const error = new Error("EACCES: permission denied");
+
+					error.code = "EACCES";
+					throw error;
+				});
+				const { ESLint: localESLint } = proxyquire(
+					"../../../lib/eslint/eslint",
+					{
+						"node:fs/promises": {
+							writeFile: spy,
+						},
+					},
+				);
+
+				await assert.rejects(
+					() =>
